-- db/seeds/brownfield/wave1/04_column_mappings.sql
-- Wave 1 column-level mapping rows (idempotent).
-- Generated by scripts/generate_wave1_column_mappings.mjs
-- One INSERT per (table_mapping, source_column) pair.
--
-- Strategy:
--   1. per-source-table OVERRIDES from BROWNFIELD_ADAPTATION_MAP §4
--   2. semantic-rule match against target column prefix
--   3. exact / prefixed name match
--   4. metadata embedding fallback (target_column = <target>_metadata)
--   5. SKIP only for pgvector embeddings (recomputable AI artifact)
--
-- All inserts use ON CONFLICT (column_mapping_table_mapping_id, column_mapping_source_column_id)
-- DO NOTHING for idempotency.

-- benchmark_configs → sys.sys_blueprint_overrides (13 columns)
WITH tm AS (
  SELECT tm.table_mapping_id
    FROM brownfield.table_mappings tm
    JOIN brownfield.source_tables st ON st.source_table_id = tm.table_mapping_source_table_id
    JOIN brownfield.source_exports se ON se.source_export_id = st.source_table_export_id
   WHERE st.source_table_name = 'benchmark_configs'
     AND st.source_table_schema = 'public'
     AND tm.table_mapping_target_schema = 'sys'
     AND tm.table_mapping_target_table = 'sys_blueprint_overrides'
     AND se.source_export_name = 'db-export-2026-05-15'
), src AS (
  SELECT sc.source_column_id, sc.source_column_name
    FROM brownfield.source_columns sc
    JOIN brownfield.source_tables st ON st.source_table_id = sc.source_column_table_id
    JOIN brownfield.source_exports se ON se.source_export_id = st.source_table_export_id
   WHERE st.source_table_name = 'benchmark_configs'
     AND st.source_table_schema = 'public'
     AND se.source_export_name = 'db-export-2026-05-15'
)
